sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading)
        return;

    var companyId = g_form.getValue('user.company');

    // If Business Unit is empty, allow manual company selection
    if (!newValue)
        return;

    var ga = new GlideAjax('IncentNowClientUtils');
    ga.addParam('sysparm_name', 'validateBusinessUnitCompany');
    ga.addParam('sysparm_company_id', companyId);
    ga.addParam('sysparm_business_unit_id', newValue);

    ga.getXMLAnswer(function(answer) {

        var result = JSON.parse(answer || '{}');

        if (!result.valid) {
            g_form.addErrorMessage('Selected Company does not match with Business Unit company.');
            g_form.clearValue('business_unit');
            return;
        }

        // If company is empty, set it from Business Unit company
        if (!companyId && result.business_unit_company) {
            g_form.setValue('user.company', result.business_unit_company);
        }
    });
}
